PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE authz_team (
	id CHAR(32) NOT NULL,
	team_name VARCHAR NOT NULL,
	adom_name VARCHAR NOT NULL,
	description VARCHAR,
	is_active BOOLEAN NOT NULL,
	created_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	PRIMARY KEY (id)
);
CREATE TABLE casbin_rule (
	id INTEGER NOT NULL,
	ptype VARCHAR(255) NOT NULL,
	v0 VARCHAR(255),
	v1 VARCHAR(255),
	v2 VARCHAR(255),
	v3 VARCHAR(255),
	v4 VARCHAR(255),
	v5 VARCHAR(255),
	PRIMARY KEY (id)
);
CREATE TABLE job (
	job_id CHAR(32) NOT NULL,
	flow_id CHAR(32) NOT NULL,
	status VARCHAR(11) NOT NULL,
	created_timestamp DATETIME NOT NULL,
	finished_timestamp DATETIME,
	type VARCHAR(10),
	user_id CHAR(32),
	asset_id CHAR(32),
	asset_type VARCHAR,
	dedupe_key VARCHAR,
	job_metadata JSON,
	PRIMARY KEY (job_id)
);
CREATE TABLE memory_base (
	name VARCHAR NOT NULL,
	flow_id CHAR(32) NOT NULL,
	user_id CHAR(32) NOT NULL,
	threshold INTEGER NOT NULL,
	auto_capture BOOLEAN NOT NULL,
	embedding_model VARCHAR NOT NULL,
	preprocessing BOOLEAN NOT NULL,
	preproc_model VARCHAR,
	preproc_instructions VARCHAR,
	preproc_kill_phrase VARCHAR,
	id CHAR(32) NOT NULL,
	kb_name VARCHAR NOT NULL,
	created_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT uq_memory_base_user_name UNIQUE (user_id, name)
);
CREATE TABLE user (
	id CHAR(32) NOT NULL,
	username VARCHAR NOT NULL,
	password VARCHAR NOT NULL,
	profile_image VARCHAR,
	is_active BOOLEAN NOT NULL,
	is_superuser BOOLEAN NOT NULL,
	create_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	last_login_at DATETIME,
	store_api_key VARCHAR,
	optins JSON,
	PRIMARY KEY (id),
	UNIQUE (id)
);
INSERT INTO user VALUES('0949659692a4409090a795f56dfe8410','langflow','$2b$12$zYqaOQDQvO9v/B0xUYXPUuoMPoeuRWEaFeyCRpgkN8AGc7qECdlPy',NULL,1,1,'2026-10-27 18:15:10.788217','2026-10-27 18:15:17.566120','2026-10-27 18:15:17.565434','','{"github_starred": false, "dialog_dismissed": false, "discord_clicked": false}');
INSERT INTO user VALUES('e1f8530c4a9f4b25ad30f1a2d6064aea','fixture-user','$2b$12$5VxYiZOv8PKdiyLIFEWwye0NTEdW9pNydARuuYjQzhGbkN8ecL5mS',NULL,0,0,'2026-10-27 18:15:17.759902','2026-10-27 18:15:17.759905',NULL,NULL,'{"github_starred": false, "dialog_dismissed": false, "discord_clicked": false}');
CREATE TABLE authz_audit_log (
	id CHAR(32) NOT NULL,
	user_id CHAR(32),
	action VARCHAR NOT NULL,
	resource_type VARCHAR,
	resource_id CHAR(32),
	result VARCHAR NOT NULL,
	details JSON,
	timestamp DATETIME NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT ck_authz_audit_log_result_enum CHECK (result IN ('allow', 'deny', 'owner_override')),
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE SET NULL
);
CREATE TABLE authz_role (
	id CHAR(32) NOT NULL,
	name VARCHAR NOT NULL,
	description VARCHAR,
	is_system BOOLEAN NOT NULL,
	permissions JSON NOT NULL,
	parent_role_id CHAR(32),
	workspace_id CHAR(32),
	created_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	created_by CHAR(32),
	PRIMARY KEY (id),
	FOREIGN KEY(parent_role_id) REFERENCES authz_role (id) ON DELETE SET NULL,
	FOREIGN KEY(created_by) REFERENCES user (id) ON DELETE SET NULL
);
INSERT INTO authz_role VALUES('7a70ca39c4cc4bc6988c6db3f7bd417f','viewer','Read-only access to flows, deployments, projects, and supporting resources.',1,'["flow:read", "flow:execute", "deployment:read", "project:read", "knowledge_base:read", "variable:read", "file:read"]',NULL,NULL,'2026-10-27 18:15:10.201193','2026-10-27 18:15:10.201193',NULL);
INSERT INTO authz_role VALUES('38f73751e7f34003af25546b4d69a835','developer','Author and execute flows; manage variables, knowledge bases, and files.',1,'["flow:read", "flow:execute", "deployment:read", "project:read", "knowledge_base:read", "variable:read", "file:read", "flow:write", "flow:create", "deployment:write", "deployment:create", "deployment:execute", "project:write", "project:create", "knowledge_base:write", "knowledge_base:create", "knowledge_base:ingest", "variable:write", "variable:create", "file:write", "file:create"]',NULL,NULL,'2026-10-27 18:15:10.201193','2026-10-27 18:15:10.201193',NULL);
INSERT INTO authz_role VALUES('fbac0b4cb58e481d9e9a0a7bbdf0e69b','admin','Full management of resources and shares within the workspace.',1,'["flow:read", "flow:execute", "deployment:read", "project:read", "knowledge_base:read", "variable:read", "file:read", "flow:write", "flow:create", "deployment:write", "deployment:create", "deployment:execute", "project:write", "project:create", "knowledge_base:write", "knowledge_base:create", "knowledge_base:ingest", "variable:write", "variable:create", "file:write", "file:create", "flow:delete", "flow:deploy", "deployment:delete", "project:delete", "knowledge_base:delete", "variable:delete", "file:delete", "share:read", "share:create", "share:update", "share:delete"]',NULL,NULL,'2026-10-27 18:15:10.201193','2026-10-27 18:15:10.201193',NULL);
CREATE TABLE authz_share (
	id CHAR(32) NOT NULL,
	resource_type VARCHAR NOT NULL,
	resource_id CHAR(32) NOT NULL,
	scope VARCHAR NOT NULL,
	target_id CHAR(32),
	permission_level VARCHAR NOT NULL,
	created_by CHAR(32),
	created_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT ck_authz_share_scope_enum CHECK (scope IN ('private', 'team', 'user', 'public')),
	CONSTRAINT ck_authz_share_permission_enum CHECK (permission_level IN ('read', 'write', 'execute', 'admin')),
	CONSTRAINT ck_authz_share_scope_target_consistency CHECK ((scope IN ('team', 'user') AND target_id IS NOT NULL) OR (scope IN ('private', 'public') AND target_id IS NULL)),
	FOREIGN KEY(created_by) REFERENCES user (id) ON DELETE SET NULL
);
CREATE TABLE authz_team_member (
	id CHAR(32) NOT NULL,
	team_id CHAR(32) NOT NULL,
	user_id CHAR(32) NOT NULL,
	source VARCHAR NOT NULL,
	created_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT uq_authz_team_member UNIQUE (team_id, user_id),
	FOREIGN KEY(team_id) REFERENCES authz_team (id) ON DELETE CASCADE,
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE CASCADE
);
CREATE TABLE folder (
	name VARCHAR NOT NULL,
	description TEXT,
	auth_settings JSON,
	id CHAR(32) NOT NULL,
	parent_id CHAR(32),
	user_id CHAR(32),
	workspace_id CHAR(32),
	PRIMARY KEY (id),
	CONSTRAINT unique_folder_name UNIQUE (user_id, name),
	FOREIGN KEY(parent_id) REFERENCES folder (id),
	FOREIGN KEY(user_id) REFERENCES user (id)
);
INSERT INTO folder VALUES('Starter Project','Manage your own flows. Download and upload projects.','null','3471fd2809314d85b4664e884c130610',NULL,'0949659692a4409090a795f56dfe8410',NULL);
INSERT INTO folder VALUES('Starter Project','Manage your own flows. Download and upload projects.','null','85b7fe75960148149d0e333617a108ab',NULL,'e1f8530c4a9f4b25ad30f1a2d6064aea',NULL);
INSERT INTO folder VALUES('Fixture project','Upgrade check fixture','null','07b90f47274649fb90d8750cf138742e',NULL,'0949659692a4409090a795f56dfe8410',NULL);
CREATE TABLE knowledge_base (
	id CHAR(32) NOT NULL,
	name VARCHAR NOT NULL,
	user_id CHAR(32) NOT NULL,
	model_selection JSON NOT NULL,
	chunk_size INTEGER NOT NULL,
	chunk_overlap INTEGER NOT NULL,
	separator VARCHAR,
	column_config JSON NOT NULL,
	backend_type VARCHAR NOT NULL,
	backend_config JSON NOT NULL,
	chunks INTEGER NOT NULL,
	words INTEGER NOT NULL,
	characters INTEGER NOT NULL,
	size_bytes BIGINT DEFAULT '0' NOT NULL,
	source_types JSON NOT NULL,
	status VARCHAR NOT NULL,
	failure_reason VARCHAR,
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT uq_knowledge_base_user_name UNIQUE (user_id, name),
	CONSTRAINT ck_knowledge_base_status CHECK (status IN ('creating', 'ready', 'ingesting', 'failed')),
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE CASCADE
);
CREATE TABLE memory_base_preprocessing_output (
	id CHAR(32) NOT NULL,
	memory_base_id CHAR(32) NOT NULL,
	session_id VARCHAR NOT NULL,
	job_id CHAR(32),
	status VARCHAR NOT NULL,
	output_text TEXT,
	source_message_ids JSON NOT NULL,
	model_used VARCHAR NOT NULL,
	created_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(memory_base_id) REFERENCES memory_base (id) ON DELETE CASCADE,
	FOREIGN KEY(job_id) REFERENCES job (job_id) ON DELETE SET NULL
);
CREATE TABLE memory_base_session (
	session_id VARCHAR NOT NULL,
	cursor_id CHAR(32),
	total_processed INTEGER NOT NULL,
	last_sync_at DATETIME,
	id CHAR(32) NOT NULL,
	memory_base_id CHAR(32) NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT uq_memory_base_session UNIQUE (memory_base_id, session_id),
	FOREIGN KEY(memory_base_id) REFERENCES memory_base (id) ON DELETE CASCADE
);
CREATE TABLE memory_base_workflow_run (
	id CHAR(32) NOT NULL,
	memory_base_id CHAR(32) NOT NULL,
	session_id VARCHAR NOT NULL,
	workflow_job_id CHAR(32),
	ingestion_job_id CHAR(32),
	recorded_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT uq_mbwr_mb_session_wf_job UNIQUE (memory_base_id, session_id, workflow_job_id),
	FOREIGN KEY(memory_base_id) REFERENCES memory_base (id) ON DELETE CASCADE,
	FOREIGN KEY(workflow_job_id) REFERENCES job (job_id) ON DELETE SET NULL,
	FOREIGN KEY(ingestion_job_id) REFERENCES job (job_id) ON DELETE SET NULL
);
CREATE TABLE message_ingestion_record (
	id CHAR(32) NOT NULL,
	message_id CHAR(32) NOT NULL,
	memory_base_id CHAR(32) NOT NULL,
	job_id CHAR(32),
	session_id VARCHAR NOT NULL,
	ingested_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT uq_mir_message_session_mb UNIQUE (message_id, session_id, memory_base_id),
	FOREIGN KEY(message_id) REFERENCES message (id) ON DELETE CASCADE,
	FOREIGN KEY(memory_base_id) REFERENCES memory_base (id) ON DELETE CASCADE,
	FOREIGN KEY(job_id) REFERENCES job (job_id) ON DELETE SET NULL
);
CREATE TABLE sso_config (
	id CHAR(32) NOT NULL,
	provider VARCHAR NOT NULL,
	provider_name VARCHAR NOT NULL,
	enabled BOOLEAN NOT NULL,
	enforce_sso BOOLEAN NOT NULL,
	client_id VARCHAR,
	client_secret_encrypted VARCHAR,
	discovery_url VARCHAR,
	redirect_uri VARCHAR,
	scopes VARCHAR,
	email_claim VARCHAR NOT NULL,
	username_claim VARCHAR NOT NULL,
	user_id_claim VARCHAR NOT NULL,
	token_endpoint VARCHAR,
	authorization_endpoint VARCHAR,
	jwks_uri VARCHAR,
	issuer VARCHAR,
	created_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	created_by CHAR(32),
	PRIMARY KEY (id),
	FOREIGN KEY(created_by) REFERENCES user (id) ON DELETE SET NULL
);
CREATE TABLE sso_user_profile (
	id CHAR(32) NOT NULL,
	user_id CHAR(32) NOT NULL,
	sso_provider VARCHAR NOT NULL,
	sso_user_id VARCHAR NOT NULL,
	email VARCHAR,
	sso_last_login_at DATETIME,
	created_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE CASCADE
);
CREATE TABLE variable (
	name VARCHAR NOT NULL,
	value VARCHAR NOT NULL,
	type VARCHAR,
	id CHAR(32) NOT NULL,
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	updated_at DATETIME,
	default_fields JSON,
	user_id CHAR(32) NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE authz_role_assignment (
	id CHAR(32) NOT NULL,
	user_id CHAR(32) NOT NULL,
	role_id CHAR(32) NOT NULL,
	domain_type VARCHAR NOT NULL,
	domain_id CHAR(32),
	assigned_at DATETIME NOT NULL,
	assigned_by CHAR(32),
	PRIMARY KEY (id),
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE CASCADE,
	FOREIGN KEY(role_id) REFERENCES authz_role (id) ON DELETE CASCADE,
	FOREIGN KEY(assigned_by) REFERENCES user (id) ON DELETE SET NULL
);
CREATE TABLE ingestion_run (
	id CHAR(32) NOT NULL,
	job_id CHAR(32),
	kb_name VARCHAR NOT NULL,
	kb_id CHAR(32),
	user_id CHAR(32),
	source_type VARCHAR NOT NULL,
	source_config JSON NOT NULL,
	status VARCHAR NOT NULL,
	error_message VARCHAR,
	total_items INTEGER NOT NULL,
	succeeded INTEGER NOT NULL,
	failed INTEGER NOT NULL,
	skipped INTEGER NOT NULL,
	total_bytes BIGINT DEFAULT '0' NOT NULL,
	chunks_created INTEGER NOT NULL,
	items JSON NOT NULL,
	user_metadata JSON DEFAULT '{}' NOT NULL,
	started_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
	finished_at DATETIME,
	PRIMARY KEY (id),
	CONSTRAINT ck_ingestion_run_status CHECK (status IN ('pending', 'running', 'succeeded', 'partial', 'failed', 'cancelled')),
	FOREIGN KEY(kb_id) REFERENCES knowledge_base (id) ON DELETE SET NULL
);
CREATE TABLE authz_edit_lock (
	id CHAR(32) NOT NULL,
	flow_id CHAR(32) NOT NULL,
	holder_user_id CHAR(32) NOT NULL,
	acquired_at DATETIME NOT NULL,
	expires_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(flow_id) REFERENCES flow (id) ON DELETE CASCADE,
	FOREIGN KEY(holder_user_id) REFERENCES user (id) ON DELETE CASCADE
);
CREATE TABLE flow_version (
	id CHAR(32) NOT NULL,
	flow_id CHAR(32) NOT NULL,
	user_id CHAR(32),
	data JSON,
	version_number INTEGER NOT NULL,
	description VARCHAR(500),
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT unique_flow_version_number UNIQUE (flow_id, version_number),
	CONSTRAINT check_version_number_positive CHECK (version_number >= 1),
	FOREIGN KEY(flow_id) REFERENCES flow (id) ON DELETE CASCADE,
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE SET NULL
);
INSERT INTO flow_version VALUES('07783ebee25141daa4186704091a6a14','509d6db9ad154466919b9261884b8f45','0949659692a4409090a795f56dfe8410','{"nodes": [{"id": "groupComponent-sR189", "type": "genericNode", "position": {"x": 0, "y": 0.0}, "data": {"id": "groupComponent-sR189", "type": "GroupNode", "node": {"display_name": "Group", "documentation": "", "description": "", "template": {"code_ChatInput-ZgTE8": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": false, "title_case": false, "type": "code", "value": "from lfx.base.data.utils import IMG_FILE_TYPES, TEXT_FILE_TYPES\nfrom lfx.base.io.chat import ChatComponent\nfrom lfx.inputs.inputs import BoolInput\nfrom lfx.io import (\n    DropdownInput,\n    FileInput,\n    MessageTextInput,\n    MultilineInput,\n    Output,\n)\nfrom lfx.schema.message import Message\nfrom lfx.utils.constants import (\n    MESSAGE_SENDER_AI,\n    MESSAGE_SENDER_NAME_USER,\n    MESSAGE_SENDER_USER,\n)\n\n\nclass ChatInput(ChatComponent):\n    display_name = \"Chat Input\"\n    description = \"Get chat inputs from the Playground.\"\n    documentation: str = \"https://docs.langflow.org/chat-input-and-output\"\n    icon = \"MessagesSquare\"\n    name = \"ChatInput\"\n    minimized = True\n\n    inputs = [\n        MultilineInput(\n            name=\"input_value\",\n            display_name=\"Input Text\",\n            value=\"\",\n            info=\"Message to be passed as input.\",\n            input_types=[],\n        ),\n        BoolInput(\n            name=\"should_store_message\",\n            display_name=\"Store Messages\",\n            info=\"Store the message in the history.\",\n            value=True,\n            advanced=True,\n        ),\n        DropdownInput(\n            name=\"sender\",\n            display_name=\"Sender Type\",\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\n            value=MESSAGE_SENDER_USER,\n            info=\"Type of sender.\",\n            advanced=True,\n        ),\n        MessageTextInput(\n            name=\"sender_name\",\n            display_name=\"Sender Name\",\n            info=\"Name of the sender.\",\n            value=MESSAGE_SENDER_NAME_USER,\n            advanced=True,\n        ),\n        MessageTextInput(\n            name=\"session_id\",\n            display_name=\"Session ID\",\n            info=\"The session ID of the chat. If empty, the current session ID parameter will be used.\",\n            advanced=True,\n        ),\n        MessageTextInput(\n            name=\"context_id\",\n            display_name=\"Context ID\",\n            info=\"The context ID of the chat. Adds an extra layer to the local memory.\",\n            value=\"\",\n            advanced=True,\n        ),\n        FileInput(\n            name=\"files\",\n            display_name=\"Files\",\n            file_types=TEXT_FILE_TYPES + IMG_FILE_TYPES,\n            info=\"Files to be sent with the message.\",\n            advanced=True,\n            is_list=True,\n            temp_file=True,\n        ),\n    ]\n    outputs = [\n        Output(display_name=\"Chat Message\", name=\"message\", method=\"message_response\"),\n    ]\n\n    async def message_response(self) -> Message:\n        # Ensure files is a list and filter out empty/None values\n        files = self.files if self.files else []\n        if files and not isinstance(files, list):\n            files = [files]\n        # Filter out None/empty values\n        files = [f for f in files if f is not None and f != \"\"]\n\n        session_id = self.session_id or self.graph.session_id or \"\"\n        message = await Message.create(\n            text=self.input_value,\n            sender=self.sender,\n            sender_name=self.sender_name,\n            session_id=session_id,\n            context_id=self.context_id,\n            files=files,\n        )\n        if session_id and isinstance(message, Message) and self.should_store_message:\n            stored_message = await self.send_message(\n                message,\n            )\n            self.message.value = stored_message\n            message = stored_message\n\n        self.status = message\n        return message\n", "proxy": {"id": "ChatInput-ZgTE8", "field": "code"}, "display_name": "Code"}, "context_id_ChatInput-ZgTE8": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Context ID", "dynamic": false, "info": "The context ID of the chat. Adds an extra layer to the local memory.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "context_id", "override_skip": false, "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "track_in_telemetry": false, "type": "str", "value": "", "proxy": {"id": "ChatInput-ZgTE8", "field": "context_id"}}, "files_ChatInput-ZgTE8": {"_input_type": "FileInput", "advanced": true, "display_name": "Files", "dynamic": false, "fileTypes": ["csv", "json", "pdf", "txt", "md", "mdx", "yaml", "yml", "xml", "html", "htm", "docx", "py", "sh", "sql", "js", "ts", "tsx", "jpg", "jpeg", "png", "bmp", "image"], "file_path": "", "info": "Files to be sent with the message.", "list": true, "list_add_label": "Add More", "name": "files", "override_skip": false, "placeholder": "", "required": false, "show": true, "temp_file": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "track_in_telemetry": false, "type": "file", "value": "", "proxy": {"id": "ChatInput-ZgTE8", "field": "files"}}, "input_value_ChatInput-ZgTE8": {"_input_type": "MultilineInput", "advanced": true, "ai_enabled": false, "copy_field": false, "display_name": "Input Text", "dynamic": false, "info": "Message to be passed as input.", "input_types": [], "list": false, "list_add_label": "Add Mo