INSERT INTO flow VALUES('Fixture saved component','A saved component.',NULL,NULL,1,'2026-10-27 18:15:17.992240',0,NULL,'{"nodes": [{"id": "ChatInput-oK3Tr", "type": "genericNode", "position": {"x": 0, "y": 0}, "selected": false, "data": {"id": "ChatInput-oK3Tr", "type": "ChatInput", "node": {"base_classes": ["Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Get chat inputs from the Playground.", "display_name": "Chat Input", "documentation": "https://docs.langflow.org/chat-input-and-output", "edited": false, "field_order": ["input_value", "should_store_message", "sender", "sender_name", "session_id", "context_id", "files"], "frozen": false, "icon": "MessagesSquare", "legacy": false, "metadata": {"code_hash": "7a26c54d89ed", "dependencies": {"dependencies": [{"name": "lfx", "version": null}], "total_dependencies": 1}, "module": "lfx.components.input_output.chat.ChatInput"}, "minimized": true, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Chat Message", "group_outputs": false, "method": "message_response", "name": "message", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__", "hidden": false, "options": null, "required_inputs": null}], "pinned": false, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from lfx.base.data.utils import IMG_FILE_TYPES, TEXT_FILE_TYPES\nfrom lfx.base.io.chat import ChatComponent\nfrom lfx.inputs.inputs import BoolInput\nfrom lfx.io import (\n    DropdownInput,\n    FileInput,\n    MessageTextInput,\n    MultilineInput,\n    Output,\n)\nfrom lfx.schema.message import Message\nfrom lfx.utils.constants import (\n    MESSAGE_SENDER_AI,\n    MESSAGE_SENDER_NAME_USER,\n    MESSAGE_SENDER_USER,\n)\n\n\nclass ChatInput(ChatComponent):\n    display_name = \"Chat Input\"\n    description = \"Get chat inputs from the Playground.\"\n    documentation: str = \"https://docs.langflow.org/chat-input-and-output\"\n    icon = \"MessagesSquare\"\n    name = \"ChatInput\"\n    minimized = True\n\n    inputs = [\n        MultilineInput(\n            name=\"input_value\",\n            display_name=\"Input Text\",\n            value=\"\",\n            info=\"Message to be passed as input.\",\n            input_types=[],\n        ),\n        BoolInput(\n            name=\"should_store_message\",\n            display_name=\"Store Messages\",\n            info=\"Store the message in the history.\",\n            value=True,\n            advanced=True,\n        ),\n        DropdownInput(\n            name=\"sender\",\n            display_name=\"Sender Type\",\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\n            value=MESSAGE_SENDER_USER,\n            info=\"Type of sender.\",\n            advanced=True,\n        ),\n        MessageTextInput(\n            name=\"sender_name\",\n            display_name=\"Sender Name\",\n            info=\"Name of the sender.\",\n            value=MESSAGE_SENDER_NAME_USER,\n            advanced=True,\n        ),\n        MessageTextInput(\n            name=\"session_id\",\n            display_name=\"Session ID\",\n            info=\"The session ID of the chat. If empty, the current session ID parameter will be used.\",\n            advanced=True,\n        ),\n        MessageTextInput(\n            name=\"context_id\",\n            display_name=\"Context ID\",\n            info=\"The context ID of the chat. Adds an extra layer to the local memory.\",\n            value=\"\",\n            advanced=True,\n        ),\n        FileInput(\n            name=\"files\",\n            display_name=\"Files\",\n            file_types=TEXT_FILE_TYPES + IMG_FILE_TYPES,\n            info=\"Files to be sent with the message.\",\n            advanced=True,\n            is_list=True,\n            temp_file=True,\n        ),\n    ]\n    outputs = [\n        Output(display_name=\"Chat Message\", name=\"message\", method=\"message_response\"),\n    ]\n\n    async def message_response(self) -> Message:\n        # Ensure files is a list and filter out empty/None values\n        files = self.files if self.files else []\n        if files and not isinstance(files, list):\n            files = [files]\n        # Filter out None/empty values\n        files = [f for f in files if f is not None and f != \"\"]\n\n        session_id = self.session_id or self.graph.session_id or \"\"\n        message = await Message.create(\n            text=self.input_value,\n            sender=self.sender,\n            sender_name=self.sender_name,\n            session_id=session_id,\n            context_id=self.context_id,\n            files=files,\n        )\n        if session_id and isinstance(message, Message) and self.should_store_message:\n            stored_message = await self.send_message(\n                message,\n            )\n            self.message.value = stored_message\n            message = stored_message\n\n        self.status = message\n        return message\n"}, "context_id": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Context ID", "dynamic": false, "info": "The context ID of the chat. Adds an extra layer to the local memory.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "context_id", "override_skip": false, "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "track_in_telemetry": false, "type": "str", "value": ""}, "files": {"_input_type": "FileInput", "advanced": true, "display_name": "Files", "dynamic": false, "fileTypes": ["csv", "json", "pdf", "txt", "md", "mdx", "yaml", "yml", "xml", "html", "htm", "docx", "py", "sh", "sql", "js", "ts", "tsx", "jpg", "jpeg", "png", "bmp", "image"], "file_path": "", "info": "Files to be sent with the message.", "list": true, "list_add_label": "Add More", "name": "files", "override_skip": false, "placeholder": "", "required": false, "show": true, "temp_file": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "track_in_telemetry": false, "type": "file", "value": ""}, "input_value": {"_input_type": "MultilineInput", "advanced": false, "ai_enabled": false, "copy_field": false, "display_name": "Input Text", "dynamic": false, "info": "Message to be passed as input.", "input_types": [], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "input_value", "override_skip": false, "password": false, "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "track_in_telemetry": false, "type": "str", "value": ""}, "sender": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "dialog_inputs": {}, "display_name": "Sender Type", "dynamic": false, "external_options": {}, "info": "Type of sender.", "name": "sender", "options": ["Machine", "User"], "options_metadata": [], "override_skip": false, "placeholder": "", "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "track_in_telemetry": true, "type": "str", "value": "User"}, "sender_name": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Sender Name", "dynamic": false, "info": "Name of the sender.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "sender_name", "override_skip": false, "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "track_in_telemetry": false, "type": "str", "value": "User"}, "session_id": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Session ID", "dynamic": false, "info": "The session ID of the chat. If empty, the current session ID parameter will be used.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "session_id", "override_skip": false, "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "track_in_telemetry": false, "type": "str", "value": ""}, "should_store_message": {"_input_type": "BoolInput", "advanced": true, "display_name": "Store Messages", "dynamic": false, "info": "Store the message in the history.", "list": false, "list_add_label": "Add More", "name": "should_store_message", "override_skip": false, "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "track_in_telemetry": true, "type": "bool", "value": true}}, "tool_mode": false}, "showNode": true}}], "edges": []}',0,NULL,NULL,'PRIVATE','8e7f2c0b04134d3a9d542f256a8cdee7','0949659692a4409090a795f56dfe8410',NULL,'null',0,'07b90f47274649fb90d8750cf138742e',NULL,NULL);
CREATE TABLE IF NOT EXISTS "vertex_build" (
	timestamp DATETIME NOT NULL,
	id VARCHAR NOT NULL,
	data JSON,
	artifacts JSON,
	params TEXT,
	build_id CHAR(32) NOT NULL,
	flow_id CHAR(32) NOT NULL,
	valid BOOLEAN NOT NULL, job_id CHAR(32),
	CONSTRAINT pk_vertex_build PRIMARY KEY (build_id)
);
CREATE TABLE IF NOT EXISTS "transaction" (
	timestamp DATETIME NOT NULL,
	vertex_id VARCHAR NOT NULL,
	target_id VARCHAR,
	inputs JSON,
	outputs JSON,
	status VARCHAR NOT NULL,
	id CHAR(32) NOT NULL,
	flow_id CHAR(32) NOT NULL,
	error VARCHAR,
	CONSTRAINT pk_transaction PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS "trace" (
	name VARCHAR NOT NULL,
	status VARCHAR(5) NOT NULL,
	start_time DATETIME NOT NULL,
	end_time DATETIME,
	total_latency_ms INTEGER NOT NULL,
	total_tokens INTEGER NOT NULL,
	flow_id CHAR(32) NOT NULL,
	session_id VARCHAR,
	id CHAR(32) NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT fk_trace_flow_id_flow FOREIGN KEY(flow_id) REFERENCES flow (id) ON DELETE CASCADE,
	FOREIGN KEY(flow_id) REFERENCES flow (id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "file" (
	id CHAR(32) NOT NULL,
	user_id CHAR(32) NOT NULL,
	name VARCHAR NOT NULL,
	path VARCHAR NOT NULL,
	size INTEGER NOT NULL,
	provider VARCHAR,
	created_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT file_name_user_id_key UNIQUE (name, user_id),
	CONSTRAINT fk_file_user_id_user FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE CASCADE,
	FOREIGN KEY(user_id) REFERENCES user (id)
);
